-- ============================================================
-- Beast Cleave: core unbind, proc wiring, script registration
-- ============================================================

-- Unbind core's spell_hun_aspect_of_the_beast.  It is registered on BOTH 13161
-- and the pet spell 61669 (data/sql/base/db_world/spell_script_names.sql), and
-- its Register() branches on m_scriptSpellId == 13161
-- (src/server/scripts/Spells/spell_hunter.cpp:378).  With 13161 repurposed the
-- script would hook EFFECT_0 expecting SPELL_AURA_UNTRACKABLE and find a dummy.
-- Core C++ is left untouched; only the binding is removed.
DELETE FROM `spell_script_names`
 WHERE (`spell_id`, `ScriptName`) IN ((13161, 'spell_hun_aspect_of_the_beast'),
                                      (61669, 'spell_hun_aspect_of_the_beast'));

-- 61669 is now fully orphaned.  It is deliberately left in place rather than
-- reused by Aspect of the Monkey (woa_2026_08_11_01.sql): its SpellName0 is
-- literally 'Aspect of the Beast', which would show on the pet's buff frame.

-- The splash must not be armor-mitigated.  The parent melee hit it is derived
-- from was already mitigated, and DamageInfo::GetDamage() is post-mitigation,
-- so letting Unit::IsDamageReducedByArmor (Unit.cpp:2233) run again double-dips.
-- 0x8000 = SPELL_ATTR0_CU_IGNORE_ARMOR (SpellInfo.h:192, loaded SpellMgr.cpp:3172).
-- Mechanic = 15 (Bleed) would do the same but drags bleed-immunity along with it.
DELETE FROM `spell_custom_attr` WHERE `spell_id` = 200739;
INSERT INTO `spell_custom_attr` (`spell_id`, `attributes`) VALUES
(200739, 0x8000);

-- ProcFlags 20 = PROC_FLAG_DONE_MELEE_AUTO_ATTACK (0x4)
--              | PROC_FLAG_DONE_SPELL_MELEE_DMG_CLASS (0x10)   (SpellMgr.h:113,116)
-- so pet specials (Claw, Bite, Gore) cleave as well as white swings.
-- SpellPhaseMask = 2 is REQUIRED because 0x10 is present: SpellMgr.cpp:2113
-- rejects a spell-class proc flag with no phase mask, and a 0 phase mask makes
-- the proc silently never fire.
-- SpellTypeMask = 1 = PROC_SPELL_TYPE_DAMAGE.
DELETE FROM `spell_proc` WHERE `SpellId` = 13161;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`,
 `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`,
 `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(13161, 0, 0, 0, 0, 0, 20, 1, 2, 0, 0, 0, 0, 100, 0, 0);

-- Two scripts on 13161 is legal: one resolves to the AuraScript (the proc, which
-- runs on the PET, since the aura is applied with TARGET_UNIT_PET), the other to
-- the SpellScript (the no-pet cast check).
DELETE FROM `spell_script_names` WHERE `spell_id` IN (13161, 200739);
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(13161,  'spell_hun_beast_cleave'),
(13161,  'spell_hun_beast_cleave_cast'),
(200739, 'spell_hun_beast_cleave_damage');

-- On 200739's Attributes = 262160 (0x40010 = SPELL_ATTR0_DO_NOT_SHEATH |
-- SPELL_ATTR0_IS_ABILITY): copied from Sweeping Strikes' extra attack (12723),
-- which is the same shape of spell -- a triggered, DamageClass NONE, Physical
-- echo of a melee hit.  SPELL_ATTR0_DO_NOT_DISPLAY was deliberately NOT set:
-- it hides a spell from the combat log as well as the spellbook, which would
-- make the cleave damage invisible to the player.  A spell that is never
-- learned cannot appear in the spellbook anyway, so the flag buys nothing.

-- Duration and cooldown: DurationIndex 8 = 15000 ms (SpellDuration.dbc), with
-- RecoveryTime 30000.  50% uptime on a long window rather than the near-constant
-- 4s/6s the first pass used -- Beast Cleave is a "commit to this pull" button,
-- not something pressed on cooldown.
--
-- The description says "For $d" rather than a literal, so it tracks
-- DurationIndex with no second edit.  Retuning is one column.
--
-- Note the interaction with the deliberate no-reapply-on-resummon decision
-- below: at 15s a dismiss/resummon now throws away materially more of the buff
-- than it did at 4s.  That is still the right trade -- a hunter with no pet has
-- nothing to cleave with -- but it is a real cost now, not a rounding error.
